 \"@deepseek-ai/dsh-agent-default-model\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-connection\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-commands\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-credentials\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-home-paths\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.0-rc.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"homepage\": \"https://github.com/12we21/cute-fat-fish-pet\",\n  \"engines\": {\n    \"node\": \">=20\",\n    \"dsh\": \">=0.2.0-rc.1\"\n  },\n  \"scripts\": {\n    \"toolchain\": \"node build/toolchain.mjs\",\n    \"build\": \"node build/build.mjs\",\n    \"list\": \"node build/build.mjs --list\",\n    \"clean\": \"node build/build.mjs --clean\",\n    \"paths\": \"node build/check-paths.mjs\",\n    \"upstream\": \"node build/compare-upstream.mjs\",\n    \"verify\": \"node stage/verify.mjs\",\n    \"check\": \"node build/check-release.mjs\",\n    \"nsi\": \"python build/nsi-syntax-check.py\",\n    \"zip\": \"python build/mkzip.py\",\n    \"exe\": \"python build/mkexe.py\"\n  }\n}\n"
