\n\t\t\t\tmessages: [createUserMessage({\r\n\t\t\t\t\tcontent: [{ type: \"image\", attachment: ref }, { type: \"text\", text: prompt }],\r\n\t\t\t\t\tsource: { kind: \"user\" }\r\n\t\t\t\t})],\r\n\t\t\t\tsystem: SW_SYSTEM,\r\n\t\t\t\ttemperature: 1,\r\n\t\t\t\tsignal: AbortSignal.timeout(90000)\r\n\t\t\t})) assembler.push(chunk);\r\n\t\t} catch (e) {\r\n\t\t\treturn { error: e instanceof Error ? e.message : String(e) };\r\n\t\t}\r\n\t\tconst text = assembler.blocks().filter((b) => b.type === \"text\").map((b) => b && typeof b.text === \"string\" ? b.text : \"\").join(\"\").trim();\r\n\t\tconst a = text.indexOf(\"{\");\r\n\t\tconst z = text.lastIndexOf(\"}\");\r\n\t\tif (a < 0 || z <= a) {\r\n\t\t\t// 本地小视觉模型经常不按 JSON 回，直接说人话。以前这里判 judge-failed，\r\n\t\t\t// 结果「看屏幕点评」一声不响；现在把整段话当点评用，情绪给个中性档。\r\n\t\t\tconst plain = text.replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '').replace(/\\s+/g, ' ').trim().slice(0, 40);\r\n\t\t\tif (!plain) return { error: \"模型没有按 JSON 回复\" };\r\n\t\t\treturn { react: true, emotion: \"thinking\", say: plain, parsed: \"plain-text\" };\r\n\t\t}\r\n\t\ttry {\r\n\t\t\tconst o = JSON.parse(text.slice(a, z + 1));\r\n\t\t\treturn { react: o.react === true, emotion: String(o.emotion || \"\"), say: String(o.say || \"\").trim().slice(0, 80) };\r\n\t\t} catch (e) {\r\n\t\t\treturn { error: \"模型 JSON 解析失败\" };\r\n\t\t}\r\n\t};\r\n\tconst SW_EMOTIONS = [\"success\", \"error\", \"thinking\", \"waiting\", \"result\", \"working\"];\r\n\t/** 情绪走工作状态通道（setState 只挑动画档位），台词一律走 /broadcast。\r\n\t *  1.2.1 的气泡 BUG 就出在这：以前只有「输给真实会话的工作状态优先级」才 broadcast，\r\n\t *  而客户端默认 whisperEnabled / workStatusEnabled 都是关的 —— 没有真实会话竞争时\r\n\t *  snap.task === say 恒成立，于是 workStatus 气泡不渲染、broadcast 也不发，\r\n\t *  点评/监测结果只写进 state.json 和后端日志，用户看到的就是「她明明有反应却没有气泡」；\r\n\t *  开着「工作状态联动」时又会在 9s clear 时让气泡突然消失。\r\n\t *  所以台词无条件 broadcast：与对话回复同一条通道，客户端 1s 轮询、不受两个开关影响。 */\r\n\tconst swSpeak = (emotion, say) => {\r\n\t\tconst petId = resolveActivePetId() || \"main\";\r\n\t\tconst emo = SW_EMOTIONS.indexOf(